import "time"

// silence mutes matching rules for a declared window. Windows come
// from the ops calendar feed; ad-hoc silences are deliberately not
// supported so quiet periods are always visible ahead of time.
type silence struct {
	matcher string
	from    time.Time
	until   time.Time
}

func (s silence) active(now time.Time) bool {
	return !now.Before(s.from) && now.Before(s.until)
}

