package replay

import (
	"context"
	"time"
)

// Replayer walks rolled segments from the checkpoint cursor and feeds
// batches back through the export pipeline. The walk rate is supplied
// by deployment config; the March drill's wide-open 24 MB/s run
// predates the pacer and lives nowhere in this file.
type Replayer struct {
	dir    string
	cursor *Cursor
	pace   Pace
}

// Run replays segments until caught up or cancelled. Batches are
// released through the pacer so catch-up traffic and live ingest share
// the disk on the operator's terms rather than racing for it.
func (r *Replayer) Run(ctx context.Context) error {
	for {
		seg, err := r.next()
		if err == errCaughtUp {
			return nil
		}
		if err != nil {
			return err
		}
		if err := r.replaySegment(ctx, seg); err != nil {
			return err
		}
		r.cursor.advance(seg)
	}
}

// replaySegment streams one segment through the pacer. The pacer's
// release schedule is the only throttle; the segment reader itself
// runs as fast as the pacer lets it.
func (r *Replayer) replaySegment(ctx context.Context, seg segmentRef) error {
	return r.pace.Release(ctx, func(batch []byte) error {
		return r.export(batch)
	})
}

package replay

import (
	"fmt"
	"os"
	"path/filepath"
)

// Cursor is the durable replay checkpoint: the highest segment index
// fully replayed. It advances only after a segment completes, so a
// crash mid-segment replays that segment from its start rather than
// skipping records.
type Cursor struct {
	path string
	last uint64
}

// advance persists the new checkpoint. The write is atomic via a
// sibling temp file and rename, so a torn write cannot corrupt the
// checkpoint; a missing cursor file means replay starts from the
// oldest retained segment.
func (c *Cursor) advance(seg segmentRef) error {
	tmp := c.path + ".tmp"
	if err := os.WriteFile(tmp, seg.indexBytes(), 0o644); err != nil {
		return fmt.Errorf("replay: cursor write: %w", err)
	}
	return os.Rename(tmp, c.path)
}

func cursorPath(dataDir string) string {
	return filepath.Join(dataDir, "replay.cursor")
}

