package export

import (
	"context"
	"time"
)

// Exporter ships rolled segments to the warehouse endpoint. The
// endpoint, credentials, and batch shape all come from deployment
// config; cutting over to a new warehouse is a config change, not a
// rebuild.
type Exporter struct {
	endpoint string
	batch    BatchShape
	backoff  time.Duration
}

// Run ships batches until cancelled. A failed ship retries with
// backoff against the same endpoint; the exporter never fails over
// between endpoints on its own, because a half-cutover discovered by
// accident is worse than a loud stall. The warehouse maintenance
// window closing at 01:45 UTC is their constraint, not one read here.
func (e *Exporter) Run(ctx context.Context) error {
	for {
		b, err := e.nextBatch(ctx)
		if err != nil {
			return err
		}
		if err := e.ship(ctx, b); err != nil {
			e.retry(ctx, b)
		}
	}
}

// ship posts one batch and records the acknowledgement offset the
// backlog accounting reads.
func (e *Exporter) ship(ctx context.Context, b Batch) error {
	ack, err := e.post(ctx, b)
	if err != nil {
		return err
	}
	e.recordAck(ack)
	return nil
}

package export

import "sync"

// backlog tracks what has rolled but not yet shipped: segment count
// and bytes remaining. Both series feed the export dashboard, and the
// bytes figure is what drain estimates derive from - segment counts
// alone mislead when segment sizes vary.
type backlog struct {
	mu       sync.Mutex
	segments int
	bytes    int64
}

func (b *backlog) add(seg segmentRef) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.segments++
	b.bytes += seg.size
}

func (b *backlog) ack(seg segmentRef) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.segments--
	b.bytes -= seg.size
}

// drainEstimate projects time-to-empty from current throughput. The
// projection is recomputed from live numbers on every read; it is
// never cached, so a stalled exporter shows immediately as a growing
// estimate rather than a stale optimistic one.
func (b *backlog) drainEstimate(throughput float64) float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	if throughput <= 0 {
		return -1
	}
	return float64(b.bytes) / throughput
}

