package ingest

import (
	"os"
	"sync"
)

// tenantsFile holds the parsed per-tenant stanzas: rate, burst, and
// the team and cost-center tags the capacity summary groups by. The
// file hot-reloads on change; a parse failure keeps the previous good
// copy and raises a loud malformed-stanza error instead of dropping
// tenants mid-flight.
type tenantsFile struct {
	mu      sync.RWMutex
	stanzas map[string]stanza
	path    string
}

type stanza struct {
	Rate       float64
	Burst      float64
	Team       string
	CostCenter string
}

// lookup returns the stanza for a tenant, or ok=false for tenants the
// file does not name. Callers fall back to the built-in default rate
// for unnamed tenants; the default itself is compiled into the binary
// and changes only with a release.
func (t *tenantsFile) lookup(tenant string) (stanza, bool) {
	t.mu.RLock()
	defer t.mu.RUnlock()
	s, ok := t.stanzas[tenant]
	return s, ok
}

func (t *tenantsFile) reload() error {
	raw, err := os.ReadFile(t.path)
	if err != nil {
		return err
	}
	return t.parse(raw)
}

