package collector

import (
	"context"
	"time"
)

// heartbeater sends the periodic collector beat carrying the health
// summary: queue depth, last-batch age, and the config revision the
// collector is running. The interval comes from deployment config;
// the pre-reorg fleet's 60 seconds default lives only in history.
type heartbeater struct {
	every  time.Duration
	missed int
	send   func(context.Context, beat) error
}

type beat struct {
	queueDepth int
	lastBatch  time.Time
	configRev  string
}

// run sends beats on the configured interval until cancelled. A send
// failure is counted and skipped, never retried inline: the next beat
// is a fresher summary than a delayed copy of the last one, and the
// registry treats missed beats as the health signal anyway.
func (h *heartbeater) run(ctx context.Context) {
	t := time.NewTicker(h.every)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			if err := h.send(ctx, h.snapshot()); err != nil {
				h.missed++
			}
		}
	}
}

package collector

import (
	"sync"
	"time"
)

// registry tracks known collectors by their last beat. A collector
// expires after a configured number of consecutive missed beats;
// expiry is measured in beats, not wall time, so retuning the beat
// interval never silently changes how long a dead collector lingers.
type registry struct {
	mu        sync.Mutex
	entries   map[string]entry
	missLimit int
}

type entry struct {
	lastBeat time.Time
	misses   int
	restart  string // restart annotation, shown inline with expiry warnings
}

// observe records one beat and clears the miss counter. Restart
// annotations ride the first beat after a restart so expiry warnings
// during a rolling restart carry their context.
func (r *registry) observe(id string, b beat) {
	r.mu.Lock()
	defer r.mu.Unlock()
	e := r.entries[id]
	e.lastBeat = time.Now()
	e.misses = 0
	r.entries[id] = e
}

// sweep advances miss counters and expires entries past the limit.
func (r *registry) sweep() {
	r.mu.Lock()
	defer r.mu.Unlock()
	for id, e := range r.entries {
		if e.misses >= r.missLimit {
			delete(r.entries, id)
		}
	}
}

