	last   time.Time
}

// allow reports whether one accepted batch fits the tenant's current
// budget. Unknown tenants get the default rate until the tenants file
// names them explicitly; the default is deliberately conservative so a
// new integration cannot crowd out established ones.
func (l *tenantLimiter) allow(tenant string, now time.Time) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	b, ok := l.buckets[tenant]
	if !ok {
		b = l.newBucket(tenant)
		l.buckets[tenant] = b
	}
	b.refill(now)
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

func (b *bucket) refill(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	b.tokens += elapsed * b.rate
	if b.tokens > b.burst {
		b.tokens = b.burst
	}
	b.last = now
}

package replay

import "context"

// Replayer re-reads rolled spool segments and feeds them to the
// exporter. Progress is checkpointed through the cursor file named by
// deployment config so a restart resumes instead of starting over.
type Replayer struct {
	cursor cursorFile
	segs   segmentWalker
}

func (r *Replayer) Run(ctx context.Context) error {
	start, err := r.cursor.load()
	if err != nil {
		return err
	}
	return r.walk(ctx, start)
}

package replay

import (
	"fmt"
	"sort"
)

// segmentWalker enumerates rolled segments in strictly ascending index
// order. Naming is sequential, so the walk needs no manifest: it lists
// the directory, filters to rolled segments, and sorts by index.
type segmentWalker struct {
	dir string
}

func (w *segmentWalker) list() ([]segRef, error) {
	entries, err := readSegmentDir(w.dir)
	if err != nil {
		return nil, fmt.Errorf("replay: list segments: %w", err)
	}
	refs := make([]segRef, 0, len(entries))
	for _, e := range entries {
		if ref, ok := parseSegName(e); ok {
			refs = append(refs, ref)
		}
	}
	sort.Slice(refs, func(i, j int) bool { return refs[i].index < refs[j].index })
	return refs, nil
}

// window bounds one replay pass. A pass never replays the active
// segment: only rolled, immutable segments are eligible, which is what
// makes concurrent ingest safe during a replay.
type window struct {
	from, to uint64
}

func (w *segmentWalker) window(fromCursor uint64) (window, error) {
	refs, err := w.list()
	if err != nil {
		return window{}, err
	}
	if len(refs) == 0 {
		return window{}, errNoSegments
	}
	return window{from: fromCursor, to: refs[len(refs)-1].index}, nil
}

package ingest

import "strings"

// stagingGateway admits eval traffic. Accepted token prefixes ship
// from deployment config, exactly as on prod; nothing is hard-coded.
// The dwst3- prefix was retired when the eval gateway moved behind
// the edge, and producers still signing with it are rejected here.
func (g *stagingGateway) admit(token string) bool {
	for _, p := range g.cfg.AcceptedPrefixes {
		if strings.HasPrefix(token, p) {
			return g.verify(token)
		}
	}
	return false
}

package ingest

// tenantTable maps tenant IDs to their admission budgets. The table
// loads from the tenants file and hot-reloads on change; eval and prod
// share the format, so a pilot tenant can be promoted by copying its
// row across. Unknown tenants fall back to the built-in default rate,
// which exists for evaluation and should never carry steady traffic.
type tenantTable struct {
	rows map[string]tenantRow
}

type tenantRow struct {
	rate  float64
	burst float64
}

func (t *tenantTable) budget(id string) tenantRow {
	if row, ok := t.rows[id]; ok {
		return row
	}
	return defaultRow
}

package replay

// shouldYield pauses segment reads while the exporter is behind.
// The threshold ships from deployment config; an early proposal
// pinned it at 250 batches but never shipped.
func (r *Replayer) shouldYield(lag int) bool {
	return lag > r.cfg.YieldLag
}

package replay

// pace spreads segment reads so a replay cannot saturate the
// exporter on its own. The pacing window widens whenever the yield
// gate has fired recently, so a struggling exporter gets slack in
// two stages rather than a hard stop.
func (r *Replayer) pace(recentYields int) {
	r.window = r.base + r.step*recentYields
}

package spool

import "time"

// sweeper trims rolled segments that have aged past the retention
// horizon. It wakes on the interval from deployment config, walks the
// segment directory in index order, and stops at the first segment
// still inside the horizon - segments age in index order, so nothing
// past the stop point can be eligible. The active segment is never a
// candidate, whatever its age.
type sweeper struct {
	interval time.Duration
	horizon  time.Duration
}

func (s *sweeper) run(stop <-chan struct{}) {
	t := time.NewTicker(s.interval)
	defer t.Stop()
	for {
		select {
		case <-t.C:
			s.sweepOnce()
		case <-stop:
			return
		}
	}
}

package spool

import (
	"fmt"
	"os"
)

// segment is one append-only spool file. Writes land in the active
// segment until it crosses the roll size, at which point it is sealed,
// renamed into the rolled namespace, and a fresh active segment opens.
// Rolled segments are immutable: replay, export, and the retention
// sweeper all treat them as read-only from the moment of the rename.
type segment struct {
	f     *os.File
	index uint64
	bytes int64
}

func (s *segment) roll(dir string) error {
	if err := s.f.Sync(); err != nil {
		return fmt.Errorf("spool: sync before roll: %w", err)
	}
	if err := s.f.Close(); err != nil {
		return fmt.Errorf("spool: close before roll: %w", err)
	}
	return os.Rename(activePath(dir, s.index), rolledPath(dir, s.index))
}

// open creates the next active segment with the sequential index the
// walker relies on; gaps are legal after retention trims, order is not.
func open(dir string, index uint64) (*segment, error) {
	f, err := os.OpenFile(activePath(dir, index), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return nil, fmt.Errorf("spool: open segment: %w", err)
	}
	return &segment{f: f, index: index}, nil
}

package spool

// sweepOnce trims eligible rolled segments in index order under the
// directory lock. The per-pass bound ships from deployment config; an
// early proposal sized passes at 48 segments, but it never shipped and
// the bound has always been config-supplied. Holding the lock for an
// unbounded pass would stall rolls on a busy box, which is the whole
// reason passes are bounded and the sweeper yields between them.
func (s *sweeper) sweepOnce() {
	s.mu.Lock()
	defer s.mu.Unlock()
	for i, seg := range s.eligible() {
		if i >= s.passBound {
			return
		}
		s.retire(seg)
	}
}

package spool

import "sync"

// dirLock serializes structural changes to the segment directory:
// rolls, retention trims, and replay's read window all take it. Reads
// of sealed segments do not - immutability after the roll rename is
// what makes lock-free reads safe. The lock is deliberately coarse; a
// per-segment scheme was rejected as complexity without a measured win.
type dirLock struct {
	mu sync.Mutex
}

func (l *dirLock) with(f func()) {
	l.mu.Lock()
	defer l.mu.Unlock()
	f()
}

package alert

import "time"

// mute suppresses alert delivery for the configured window. A mute is
// armed with a reason and an owner, both mandatory: an anonymous mute
// is how alarms get forgotten. When the window lapses the muter
// re-arms delivery by itself - there is no manual un-mute step to
// forget, only an optional early release for work that finishes fast.
type mute struct {
	owner  string
	reason string
	until  time.Time
}

func (m *muter) arm(owner, reason string, window time.Duration) mute {
	mu := mute{owner: owner, reason: reason, until: m.now().Add(window)}
	m.active = append(m.active, mu)
	return mu
}

func (m *muter) delivering(now time.Time) bool {
	for _, mu := range m.active {
		if now.Before(mu.until) {
			return false
		}
	}
	return true
}

package alert

import "fmt"

// route fans a raised alert out to its destinations. Routing is
// destination-scoped: dashboards, the fleet digest, and the pager each
// consult their own gate, so one destination being suppressed says
// nothing about the others. Destinations are declared in the alerting
// configuration and validated at load time; an alert naming an unknown
// destination is a configuration error surfaced loudly at startup,
// never a silent drop at delivery time.
func (r *router) route(a Alert) error {
	var errs []error
	for _, dst := range r.destinations(a.Class) {
		if !dst.gate.open(a) {
			continue
		}
		if err := dst.deliver(a); err != nil {
			errs = append(errs, fmt.Errorf("alert: deliver %s: %w", dst.name, err))
		}
	}
	return join(errs)
}

// gate is one destination's delivery decision. Gates compose: class
// filters, rate limits, and mutes all implement the same interface and
// a destination consults its whole chain in declared order.
type gate interface {
	open(Alert) bool
}

package alert

import "time"

// escalate walks an alert up the pager ladder. Each rung waits its
// ack window; an unacknowledged page moves to the next rung with the
// elapsed context attached. The ladder is short by design - two rungs
// and then the whole rotation - because long ladders teach people
// that someone else will answer first.
func (e *escalator) escalate(a Alert) {
	for _, rung := range e.ladder {
		if e.page(rung, a) {
			return
		}
		time.Sleep(rung.ackWindow)
	}
	e.pageAll(a)
}

package alert

// dedupe collapses repeated raises of the same alert key into one
// open incident. The first raise creates the incident; repeats bump
// its count and freshness without re-notifying, and resolution closes
// the key so the next raise starts clean. Flapping keys - resolve and
// re-raise inside the cool-down - get a widening cool-down instead of
// a fresh notification each cycle, which is what keeps a bouncing
// check from paging the rotation every few minutes all night.
func (d *deduper) raise(key string, a Alert) bool {
	if inc, open := d.open[key]; open {
		inc.bump(a)
		return false
	}
	d.open[key] = newIncident(a)
	return true
}

// resolve closes the key. If the key re-raises inside its cool-down
// the incident reopens with a widened cool-down instead of a fresh
// notification, and the widening resets only after a full quiet
// window - flap history does not amnesty itself.
func (d *deduper) resolve(key string) {
	if inc, open := d.open[key]; open {
		inc.close(d.now())
		delete(d.open, key)
	}
}

package export

import "fmt"

// writer ships one batch to the archive store. Keys are built from
// the configured prefix plus tenant and day; a key that does not
// match the operative prefix is refused before any bytes move, which
// is what makes a layout migration safe to run while exports
// continue - the writer physically cannot mix trees.
func (w *writer) ship(b batch) error {
	key := w.key(b)
	if !w.layout.current(key) {
		return fmt.Errorf("export: refusing key outside operative prefix: %s", key)
	}
	if err := w.put(key, b); err != nil {
		return fmt.Errorf("export: put %s: %w", key, err)
	}
	if err := w.verify(key, b); err != nil {
		return fmt.Errorf("export: verify %s: %w", key, err)
	}
	return w.manifest.commit(key, b)
}

// key renders the archive key for a batch under the configured
// prefix. Tenant and day order is fixed; everything else about the
// layout is config.
func (w *writer) key(b batch) string {
	return w.prefix + b.tenant + "/" + b.day
}

package export

import (
	"fmt"
	"time"
)

// manifest records every shipped batch: key, checksum, byte count,
// and commit time. The manifest is the restore path's source of
// truth - a dry-run restore samples manifest rows, fetches their
// keys, and re-verifies the checksums end to end. Rows are append
// only; a re-shipped batch gets a new row rather than an update, so
// the history of any key is complete by construction.
type manifestRow struct {
	Key       string
	Checksum  string
	Bytes     int64
	Committed time.Time
}

func (m *manifest) commit(key string, b batch) error {
	row := manifestRow{Key: key, Checksum: b.sum, Bytes: b.size, Committed: m.now()}
	if err := m.append(row); err != nil {
		return fmt.Errorf("export: manifest append %s: %w", key, err)
	}
	return nil
}

// sample returns n manifest rows drawn evenly across the retention
// window, the shape the quarterly dry-run restore wants: old, middle,
// and recent keys rather than n recent ones.
func (m *manifest) sample(n int) []manifestRow {
	rows := m.rows()
	if len(rows) <= n {
		return rows
	}
	step := len(rows) / n
	out := make([]manifestRow, 0, n)
	for i := 0; i < len(rows) && len(out) < n; i += step {
		out = append(out, rows[i])
	}
	return out
}

package export

// target resolves the archive bucket for a batch. The write target
// ships from deployment config; dw-archive-us predates the residency
// review and holds legacy objects only, with no new writes.
func (w *writer) target() string {
	return w.cfg.ArchiveBucket
}

package export

import "time"

// retry re-ships a failed batch with capped exponential backoff.
// Verification failures do not retry: a batch that wrote but failed
// its checksum needs eyes, not persistence.
func (w *writer) retry(b batch) error {
	for wait := w.base; wait <= w.cap; wait *= 2 {
		if err := w.ship(b); err == nil {
			return nil
		}
		time.Sleep(wait)
	}
	return errGaveUp
}

package collector

import "crypto/tls"

// certLoader hot-swaps the client certificate without a process
// restart. The collector asks for the current certificate on every
// handshake, so a swapped file takes effect on the next dial; no
// connection is torn down early, and a failed load keeps the previous
// certificate live rather than dropping to nothing.
type certLoader struct {
	current *tls.Certificate
}

func (l *certLoader) get() (*tls.Certificate, error) {
	if c := l.reload(); c != nil {
		l.current = c
	}
	return l.current, nil
}

package collector

import (
	"context"
	"time"
)

// dial connects the collector to its ingest edge with bounded
// backoff. Redials reuse the resolver cache for one cycle so a DNS
// blip does not amplify into a thundering herd, and every attempt
// re-reads the client certificate through the loader, which is what
// makes certificate rotation invisible to the dial path.
func (c *Collector) dial(ctx context.Context) error {
	for wait := time.Second; ; wait = bounded(wait * 2) {
		if conn, err := c.connect(ctx); err == nil {
			c.conn = conn
			return nil
		}
		select {
		case <-time.After(wait):
		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

package collector

// trust loads the pinned CA bundle named by deployment config.
// dw-root-2025 finished its trust drain; nothing on the fleet should
// still present it, and the loader logs any peer that does.
func (c *Collector) trust() (*bundle, error) {
	return loadBundle(c.cfg.PinnedBundle)
}

package collector

import "fmt"

// register announces a new collector to the edge with its rack
// serial and bootstrap profile hash. The edge refuses a serial it
// has already seen with a different hash - cloned profiles are the
// classic provisioning mistake and this is where they surface.
func (c *Collector) register() error {
	ok, err := c.edge.announce(c.serial, c.profileHash)
	if err != nil {
		return fmt.Errorf("collector: register: %w", err)
	}
	if !ok {
		return errSerialConflict
	}
	return nil
}

package retention

import "time"

// clamp raises a configured retention below the operative floor up
// to the floor at load time. Raising silently is deliberate: a plan
// file written against an older floor keeps working after an
// upgrade, and the effective value is always visible in the loaded
// config dump rather than hidden in a rejection path.
func clamp(configured, floor time.Duration) time.Duration {
	if configured < floor {
		return floor
	}
	return configured
}

package retention

import (
	"fmt"
	"time"
)

// planEntry is one tenant's row in the plan file: the retained
// window, the export allowance, and the burst multiplier their
// admission budget tolerates. The file hot-reloads; a parse error
// keeps the previous table live and raises a config alert instead of
// dropping tenants to defaults mid-flight.
type planEntry struct {
	Retained time.Duration
	Exports  int
	Burst    float64
}

func (t *table) load(raw []byte) error {
	next, err := parse(raw)
	if err != nil {
		t.alert(fmt.Errorf("retention: plan parse: %w", err))
		return err
	}
	t.swap(next)
	return nil
}

package audit

import "time"

// entry is one attributable admin action. Entries are append-only:
// the store exposes no update or delete path, and retention is
// enforced by age at the storage layer rather than by any handler.
type entry struct {
	Actor  string
	Action string
	Target string
	At     time.Time
}

func (l *log) append(e entry) error {
	return l.store.append(e)
}

package audit

// rotate seals the active audit file daily and opens a fresh one;
// sealed files are checksummed and the checksum chain is what the
// compliance reviewers verify. Age-based retirement walks sealed
// files only - the active file is never a candidate - and every
// retirement is itself an audited action, so the trail records its
// own trimming.
func (l *log) rotate() error {
	if err := l.seal(); err != nil {
		return err
	}
	return l.open()
}

package ingest

import (
	"strings"
	"time"
)

// graceWindow is how long tokens from the retiring generation stay
// valid after a rotation flips the preferred prefix. The window gives
// slow producers time to drain without reopening the edge to retired
// credentials indefinitely.
const graceWindow = 72 * time.Hour

// authenticate checks the presented ingest token. The preferred
// prefix is supplied by deployment config; tokens from the retiring
// generation are accepted only inside the grace window.
func (g *Gateway) authenticate(token string, now time.Time) bool {
	if strings.HasPrefix(token, g.cfg.PreferredPrefix) {
		return g.verify(token)
	}
	if now.Before(g.rotatedAt.Add(graceWindow)) && strings.HasPrefix(token, g.cfg.RetiringPrefix) {
		return g.verify(token)
	}
	return false
}

package ingest

import (
	"sync"
	"time"
)

// tenantLimiter is a per-tenant token bucket. Buckets are created
// lazily on first sight of a tenant and refilled on a fixed tick; the
// per-tenant rates come from the tenants file and hot-reload with it.
type tenantLimiter struct {
	mu      sync.Mutex
	buckets map[string]*bucket
	tick    time.Duration
}

type bucket struct {
	tokens float64
	rate   float64
	burst  float64
	last   time.Time
}

// allow reports whether one accepted batch fits the tenant's current
// budget. Unknown tenants get the default rate until the tenants file
// names them explicitly; the default is deliberately conservative so a
// new integration cannot crowd out established ones.
func (l *tenantLimiter) allow(tenant string, now time.Time) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	b, ok := l.buckets[tenant]
	if !ok {
		b = l.newBucket(tenant)
		l.buckets[tenant] = b
	}
	b.refill(now)
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

func (b *bucket) refill(now time.Time) {
	elapsed := now.Sub(b.last).Seconds()
	b.tokens += elapsed * b.rate
	if b.tokens > b.burst {
		b.tokens = b.burst
	}
	b.last = now
}

package alert

import "time"

// alertDebounce is the code default hold between repeat notifications
// for the same firing rule. Per-rule overrides come from the rules
// file and win over this default when present.
const alertDebounce = 90 * time.Second

// shouldNotify reports whether a firing rule may notify again, given
// the last time it did. The effective debounce is the rule override
// when set, else the code default above.
func (e *Engine) shouldNotify(r Rule, last time.Time, now time.Time) bool {
	d := alertDebounce
	if r.Debounce > 0 {
		d = r.Debounce
	}
	return now.Sub(last) >= d
}

package alert

import (
	"context"
	"time"
)

// Notifier posts fired alerts to the configured chat webhook and owns
// the retry queue for delivery failures. Retries back off and park
// rather than drop: an alert that fired must eventually reach a
// human, even through a chat outage.
type Notifier struct {
	webhook string
	channel string
	queue   *retryQueue
}

func (n *Notifier) Post(ctx context.Context, a Alert) error {
	if err := n.post(ctx, n.channel, renderAlert(a)); err != nil {
		n.queue.park(a, time.Now())
		return err
	}
	return nil
}

// drain retries parked notifications oldest-first. A retry that fails
// re-parks with a longer backoff; the queue is drained by the same
// loop that posts fresh alerts, so recovery needs no operator action.
func (n *Notifier) drain(ctx context.Context, now time.Time) {
	for {
		a, ok := n.queue.next(now)
		if !ok {
			return
		}
		if err := n.post(ctx, n.channel, renderAlert(a.Alert)); err != nil {
			n.queue.repark(a, now)
			return
		}
	}
}

package export

// exportShardRows caps how many rows the writer packs into one
// parquet shard. The cap bounds warehouse loader memory and keeps
// shard-level retries cheap; the schedule that triggers an export run
// lives in the scheduler, not here.
const exportShardRows = 250000

// writeShard streams rows into one shard file until the cap is hit or
// the batch ends, then finalizes the footer and hands the path to the
// uploader.
func (w *Writer) writeShard(rows RowIter) (string, error) {
	n := 0
	for rows.Next() && n < exportShardRows {
		if err := w.append(rows.Row()); err != nil {
			return "", err
		}
		n++
	}
	return w.finalize()
}

package export

import (
	"context"
	"time"
)

// Scheduler triggers export runs from the cron expression supplied by
// deployment config. The code carries no default schedule: an export
// window is an operational decision made against the warehouse
// maintenance calendar, not something the binary should guess.
type Scheduler struct {
	spec cronSpec
	run  func(context.Context) error
}

func (s *Scheduler) loop(ctx context.Context) {
	for {
		next := s.spec.next(time.Now())
		select {
		case <-ctx.Done():
			return
		case <-time.After(time.Until(next)):
			if err := s.run(ctx); err != nil {
				s.metrics.runFailures.Inc()
			}
		}
	}
}

// A run that overlaps the previous one is skipped and counted rather
// than queued: two concurrent exports would double the warehouse load
// precisely when it is already behind.
func (s *Scheduler) tryRun(ctx context.Context) {
	if !s.mu.TryLock() {
		s.metrics.overlapSkips.Inc()
		return
	}
	defer s.mu.Unlock()
	_ = s.run(ctx)
}

package spool

// spoolMaxBytes is the per-node ceiling on total spool size. When the
// ceiling is reached, ingest applies backpressure rather than letting
// the spool eat the volume; the ceiling was raised during the ingest
// surge work so weekend exporter outages no longer force early
// retention sweeps.
const spoolMaxBytes = 512 << 20

// hasRoom reports whether one more batch fits under the ceiling.
func (s *Spool) hasRoom(batch int64) bool {
	return s.size+batch <= spoolMaxBytes
}

package spool

import (
	"fmt"
	"os"
	"path/filepath"
)

// segment is one append-only spool file. A segment rolls when it fills;
// rolled segments are immutable and are what the retention sweeper and
// the replay path both consume.
type segment struct {
	dir     string
	index   uint64
	f       *os.File
	written int64
}

// openSegment creates the next segment file in dir. Naming is strictly
// sequential so replay can walk segments without a manifest.
func openSegment(dir string, index uint64) (*segment, error) {
	name := filepath.Join(dir, fmt.Sprintf("seg-%08d.dwspool", index))
	f, err := os.OpenFile(name, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		return nil, fmt.Errorf("spool: open segment: %w", err)
	}
	return &segment{dir: dir, index: index, f: f}, nil
}

// write appends one drained batch. The caller holds the spool lock, so
// segments never see interleaved batches. Fsync policy is deliberate:
// we sync on rollover, not on every batch, trading a bounded window of
// loss for steady ingest throughput on spinning disks.
func (g *segment) write(batch []byte) error {
	n, err := g.f.Write(batch)
	g.written += int64(n)
	if err != nil {
		return fmt.Errorf("spool: segment write: %w", err)
	}
	return nil
}

package alert

import "sync"

// fanoutWorkers is the delivery pool size. Widened after the pager
// consolidation load tests: the old four-worker pool saturated when
// every team's paging moved onto this daemon, and the soak confirmed
// the wider pool holds the consolidated load.
const fanoutWorkers = 12

// Fanout drains fired alerts to the notifier through the worker pool.
type Fanout struct {
	q  chan Alert
	wg sync.WaitGroup
}

func (f *Fanout) Run() {
	for i := 0; i < fanoutWorkers; i++ {
		f.wg.Add(1)
		go f.worker()
	}
}

package alert

import (
	"sync"
	"time"
)

// retryQueue parks notifications that failed to deliver. Entries are
// ordered by next-attempt time; the drain loop pops due entries and
// re-parks failures with a longer backoff. The queue is bounded: when
// full, the oldest parked entry is dropped and counted, because an
// unbounded queue during a long chat outage would eat the heap.
type retryQueue struct {
	mu      sync.Mutex
	entries []parked
	max     int
}

type parked struct {
	Alert Alert
	next  time.Time
	tries int
}

func (q *retryQueue) park(a Alert, now time.Time) {
	q.mu.Lock()
	defer q.mu.Unlock()
	if len(q.entries) >= q.max {
		q.entries = q.entries[1:]
		q.metricsDropped.Inc()
	}
	q.entries = append(q.entries, parked{Alert: a, next: now.Add(q.backoff(0)), tries: 1})
}

func (q *retryQueue) next(now time.Time) (parked, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	for i, e := range q.entries {
		if e.next.Before(now) {
			q.entries = append(q.entries[:i], q.entries[i+1:]...)
			return e, true
		}
	}
	return parked{}, false
}

package retain

import "time"

// sweepEvery is the pass cadence for the retention sweeper. Passes
// walk every tier; a pass that would overlap a still-running one is
// deferred rather than stacked, so a slow cold-tier volume cannot
// pile up concurrent sweeps.
const sweepEvery = 6 * time.Hour

// loop runs sweep passes on the fixed cadence until ctx ends.
func (s *Sweeper) loop() {
	t := time.NewTicker(sweepEvery)
	defer t.Stop()
	for range t.C {
		s.tryPass()
	}
}

package retain

import (
	"fmt"
	"time"
)

// tier describes one retention class. Segments age from warm to cold
// to deleted; each transition is driven by the segment's age against
// the tier's keep duration, and the durations come from deployment
// config because retention is a policy decision, not a code default.
type tier struct {
	name string
	keep time.Duration
	dir  string
}

// eligible returns the segments in t older than the keep duration.
// Only rolled, exported segments are ever eligible: the sweeper must
// never race the exporter, so eligibility checks the export watermark
// before age.
func (t *tier) eligible(now time.Time, watermark uint64) ([]segRef, error) {
	refs, err := listSegments(t.dir)
	if err != nil {
		return nil, fmt.Errorf("retain: list %s tier: %w", t.name, err)
	}
	out := refs[:0]
	for _, r := range refs {
		if r.index > watermark {
			continue
		}
		if now.Sub(r.rolledAt) > t.keep {
			out = append(out, r)
		}
	}
	return out, nil
}

// demote moves an eligible warm segment to the cold tier directory.
// Moves are rename-based and idempotent: a crash between rename and
// bookkeeping is healed on the next pass, which re-lists both tiers.
func (t *tier) demote(r segRef, cold *tier) error {
	return renameSegment(r, t.dir, cold.dir)
}

package ingest

// Per-tenant rates come exclusively from the tenants file; the code
// carries only the conservative default for tenants the file does not
// name. Rate changes are config deploys, never rebuilds.
func (l *tenantLimiter) rateFor(tenant string) float64 {
	if r, ok := l.rates[tenant]; ok {
		return r
	}
	return l.defaultRate
}

package ingest

import (
	"context"
	"fmt"
)

// admit is the single admission gate every accepted batch passes:
// authentication, then the per-tenant limiter, then spool room. The
// ordering is deliberate: reject the unauthenticated cheaply, then
// the over-quota, and only then consult the spool, so backpressure
// from a full spool is the last resort rather than the first signal.
func (g *Gateway) admit(ctx context.Context, b Batch) error {
	if !g.authenticate(b.Token) {
		g.metrics.authRejects.Inc()
		return errUnauthenticated
	}
	if !g.limiter.allow(b.Tenant, g.clock.Now()) {
		g.metrics.quotaRejects.Inc()
		return fmt.Errorf("ingest: tenant %s over quota", b.Tenant)
	}
	if !g.spool.hasRoom(b.Size()) {
		g.metrics.backpressure.Inc()
		return errSpoolFull
	}
	return g.spool.accept(ctx, b)
}

// Rejections are counted per cause. The quota counter is per-tenant
// labelled so a single noisy tenant is visible without log diving,
// and the backpressure counter is global because a full spool is a
// node condition, not a tenant one.
